export class LockError extends Error {
  constructor(message: string, public readonly code: string) { super(message); this.name = 'LockError'; }
}
export class LockTimeoutError extends LockError {
  constructor(public readonly key: string, waitedMs: number) {
    super(`Timed out waiting for lock "${key}" (${waitedMs}ms)`, 'LOCK_TIMEOUT'); this.name = 'LockTimeoutError';
  }
}
export class LockConflictError extends LockError {
  constructor(public readonly key: string, public readonly currentOwner: string) {
