**`lock-manager/lock-utils.ts`** (pure, explicit args, zero state)
```ts
import type { Lock, LockRecord, LockOptions } from './types';
const DEFAULT_NAMESPACE = 'lock';
export function getLockKey(resource: string, namespace = DEFAULT_NAMESPACE): string { return `${namespace}:${resource}`; }
export function isLockExpired(lock: LockRecord, now = Date.now()): boolean { return lock.expiresAt <= now; }
export function createLock(resource: string, owner: string, ttlMs: number, token: string, opts?: Pick<LockOptions,'namespace'>): Lock {
  const now = Date.now(); const key = getLockKey(resource, opts?.namespace);
  return { key, resource, owner, token, createdAt: now, expiresAt: now + ttlMs };
}
```

**`lock-manager/events.ts`** (standalone publishers, emitter as first arg)
```ts
import type { EventEmitter } from 'node:events';
import type { Lock, LockStatus } from './types';
export function publishLockAcquired(em: EventEmitter, lock: Lock): void { em.emit('acquired', lock); }
export function publishLockReleased(em: EventEmitter, lock: Lock, reason: 'manual'|'expired'|'error'): void { em.emit('released', lock, reason); }
export function publishLockRenewed(em: EventEmitter, lock: Lock, newExpiresAt: number): void { em.emit('renewed', lock, newExpiresAt); }
export function publishLockExpired(em: EventEmitter, lock: Lock): void { em.emit('expired', lock); }
export function publishLockRejected(em: EventEmitter, lock: Lock, reason: string): void { em.emit('rejected', lock, reason); }
export function publishLockFailed(em: EventEmitter, lock: Lock, err: unknown): void { em.emit('failed', lock, err); }
export function broadcastLockStatus(em: EventEmitter, status: LockStatus, lock: Lock): void { em.emit('status', status, lock); }
```

**`lock-manager/core.ts`** (stateful class delegates to helpers/publishers)
```ts
import { EventEmitter } from 'node:events';
import type { Lock, LockOptions, LockRecord, LockStore } from './types';
import { LockTimeoutError } from './errors';
import { createLock, getLockKey, isLockExpired } from './lock-utils';
import { publishLockAcquired, publishLockExpired, publishLockReleased, publishLockRenewed, publishLockRejected } from './events';

export interface LockManagerOptions { store: LockStore; emitter?: EventEmitter; namespace?: string; }

export class LockManager {
  readonly emitter: EventEmitter;
  private readonly store: LockStore;
  private readonly namespace?: string;
  constructor(opts: LockManagerOptions) { this.store = opts.store; this.emitter = opts.emitter ?? new EventEmitter(); this.namespace = opts.namespace; }

  async tryAcquire(resource: string, owner: string, opts: LockOptions = {}): Promise<Lock | null> {
    const ttlMs = opts.ttlMs ?? 30_000;
    const lock = createLock(resource, owner, ttlMs, crypto.randomUUID(), { namespace: this.namespace ?? opts.namespace });
    const current = await this.store.get(lock.key);
    if (current && !isLockExpired(current)) { publishLockRejected(this.emitter, lock, `held by ${current.owner}`); return null; }
    await this.store.set(lock.key, lock);            // stale locks are overwritten
    publishLockAcquired(this.emitter, lock);
    return lock;
  }

  async acquire(resource: string, owner: string, opts: LockOptions = {}): Promise<Lock> {
    const acquireTimeoutMs = opts.acquireTimeoutMs ?? 5_000, retryMs = opts.retryMs ?? 50, deadline = Date.now() + acquireTimeoutMs;
    for (;;) {
      const lock = await this.tryAcquire(resource, owner, opts);
      if (lock) return lock;
      if (Date.now() >= deadline) throw new LockTimeoutError(getLockKey(resource, this.namespace ?? opts.namespace), acquireTimeoutMs);
      await new Promise(r => setTimeout(r, retryMs));
    }
  }

  async release(lock: Lock): Promise<boolean> {          // token-safe unlock
    const current = await this.store.get(lock.key);
    if (!current || current.token !== lock.token) return false;
    await this.store.del(lock.key);
    publishLockReleased(this.emitter, lock, 'manual');
    return true;
  }

  async renew(lock: Lock, ttlMs: number): Promise<Lock> {
    const current = await this.store.get(lock.key);
    if (!current || current.token !== lock.token) { publishLockExpired(this.emitter, lock); throw new LockTimeoutError(lock.key, ttlMs); }
    const next = { ...lock, expiresAt: Date.now() + ttlMs };
    await this.store.set(lock.key, next);
    publishLockRenewed(this.emitter, lock, next.expiresAt);
    return next;
  }
}
```

**`lock-manager/middleware.ts`** (express type import lives only here)
```ts
import type { NextFunction, Request, Response } from 'express';
import type { LockManager } from './core';
import type { LockOptions } from './types';

export interface AcquireLockMiddlewareOptions extends LockOptions {
  resource?: (req: Request) => string | Promise<string>;
  owner?: (req: Request) => string;
}
export function acquireLockMiddleware(manager: LockManager, opts: AcquireLockMiddlewareOptions = {}) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      const resource = opts.resource ? await opts.resource(req) : req.path;
      const owner = opts.owner ? opts.owner(req) : (req.ip ?? 'anonymous');
      res.locals.lock = await manager.acquire(resource, owner, opts);
      const done = () => { void manager.release(res.locals.lock); };
      res.once('finish', done); res.once('close', done);
      next();
    } catch (err) { next(err); }
  };
}
```

