```ts
import { parse } from "yaml";

/**
 * Merges a YAML entity file's frontmatter (structured metadata) with its
 * body string. Extracted from the identical inline block in
 * listEntities() and getAllEntitiesFromCache(); callers now share one path.
 */
export function parseEntityYaml<T extends { id: string }>(raw: string): T {
  const parsed = parse(raw) as Record<string, unknown> | null;
  if (parsed === null || typeof parsed !== "object") {
    return { body: raw } as T; // body-only file: raw content becomes the body
  }
  const { body, ...frontmatter } = parsed;
  return {
    ...(frontmatter as Record<string, unknown>),
    body: typeof body === "string" ? body : raw,
  } as T;
}
```

