import { promises as fs } from "node:fs";
import path from "node:path";

/** Recursively create the entity storage directory for a project. */
export async function ensureDirectoryStructure(
  projectPath: string,
  indexPath: string,
): Promise<void> {
  await fs.mkdir(path.join(projectPath, indexPath), { recursive: true });
}

/** Resolve the file path for a full entity object (sub-paths by kind/type). */
export function getEntityFilePath(
  projectPath: string,
  indexPath: string,
  entity: { id: string; type?: string },
): string {
  const rel = entity.type ? path.join(entity.type, `${entity.id}.yaml`) : `${entity.id}.yaml`;
  return path.join(projectPath, indexPath, rel);
}

/** Resolve the file path from an entity id string. */
export function getEntityFilePathById(
  projectPath: string,
  indexPath: string,
  id: string,
): string {
  return path.join(projectPath, indexPath, `${id}.yaml`);
}
