const ALLOWED = new Set(['http:', 'https:', 'mailto:']);

export function sanitizeUrl(input: unknown): string {
  const s = String(input).trim();
  try {
    const u = new URL(s);
    return ALLOWED.has(u.protocol) ? u.href : '';
  } catch { return ''; }
}
```

